@import url('https://fonts.googleapis.com/css2?family=Exo+2:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* FC Barcelona DNA — blaugrana night navy, garnet and gold, més que un club */
.theme-barcelona-dna {
  --bg: oklch(0.213 0.072 278.4);
  --surface: oklch(0.255 0.084 276.8);
  --surface-2: oklch(0.301 0.103 276.8);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.725 0.055 280.2);
  --accent: oklch(0.462 0.185 8.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.814 0.166 89.2);
  --line: oklch(1 0 0 / 15%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.814 0.166 89.2);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Exo 2", sans-serif;
  --font-body: "Exo 2", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-barcelona-dna h1,
.theme-barcelona-dna h2,
.theme-barcelona-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-barcelona-dna { background-image: repeating-linear-gradient(90deg, oklch(0.35 0.14 15 / 12%) 0 80px, transparent 80px 160px); }
.theme-barcelona-dna h1 { text-transform: uppercase; }
.theme-barcelona-dna h1::after { content: ""; display: block; height: 3px; width: 5rem; margin-top: 0.6rem; background: var(--accent-2); }
.theme-barcelona-dna button { font-weight: 700; }

/* depth */
.theme-barcelona-dna thead th { background: var(--surface); color: var(--accent-2); text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.78em; border-bottom: 2px solid var(--accent); }
.theme-barcelona-dna td { border-bottom: 1px solid var(--line); }
.theme-barcelona-dna tbody tr:hover { background: oklch(0.35 0.14 15 / 18%); }
.theme-barcelona-dna a { color: var(--accent-2); text-underline-offset: 3px; text-decoration-color: oklch(0.55 0.18 10 / 70%); }
.theme-barcelona-dna a:hover { text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; }
.theme-barcelona-dna ::selection { background: oklch(0.462 0.185 8.3); color: oklch(1 0 0); }
.theme-barcelona-dna input:focus-visible, .theme-barcelona-dna select:focus-visible, .theme-barcelona-dna textarea:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }
.theme-barcelona-dna kbd { background: oklch(0.30 0.10 277); border: 1px solid var(--line); border-bottom-width: 3px; border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-barcelona-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-barcelona-dna ::-webkit-scrollbar-track { background: oklch(0.18 0.06 278); }
.theme-barcelona-dna ::-webkit-scrollbar-thumb { background: oklch(0.42 0.15 10); border-radius: 5px; border: 2px solid oklch(0.18 0.06 278); }
.theme-barcelona-dna ::-webkit-scrollbar-thumb:hover { background: oklch(0.50 0.17 10); }
.theme-barcelona-dna .label-caps { color: var(--accent-2); }
/* senyera strip — the Catalan bars from the crest */
.theme-barcelona-dna .themed-border { border-image: repeating-linear-gradient(90deg, oklch(0.814 0.166 89.2) 0 10px, oklch(0.55 0.21 25) 10px 20px) 1; }
.theme-barcelona-dna button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-barcelona-dna.alt-mode {
  --bg: oklch(0.156 0.008 285.4);
  --surface: oklch(0.199 0.012 285.3);
  --surface-2: oklch(0.243 0.015 285.2);
  --fg: oklch(0.949 0.013 306.0);
  --fg-muted: oklch(0.663 0.023 303.9);
  --accent: oklch(0.539 0.188 296.6);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.767 0.139 91.1);
  --line: oklch(0.6 0.12 300 / 30%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: radial-gradient(ellipse at 50% 115%, oklch(0.45 0.18 300 / 45%), transparent 60%);
}
.theme-barcelona-dna.alt-mode h1::after { background: #d4af37; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
